from collections import deque

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if not v or v==2 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                x,y=q.pop(); comp.append((x,y))
                for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and g[nx][ny]==v:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps.append((v,comp))
    # move toward color-2 boundary direction
    direction = 1 if any(all(v==2 for v in row) for row in g[:1]) else -1
    # infer row2 boundary at bottom -> down; at top -> up
    if any(all(v==2 for v in row) for row in g[0]): direction=1
    elif any(all(v==2 for v in row) for row in g[-1]): direction=-1
    else: direction=1
    # simultaneous one-cell shifts, preserving components
    while True:
        occupancy={(r,c) for r in range(h) for c in range(w) if g[r][c] not in (0,2)}
        moves=[]
        for i,(v,co) in enumerate(comps):
            dest=[(r+direction,c) for r,c in co]
            if all(0<=r<h and g[r][c] in (0,v) and (r,c) not in occupancy or (r,c) in co for r,c in dest):
                moves.append(i)
        if not moves: break
        for i in moves:
            v,co=comps[i]
            for r,c in co:g[r][c]=0
        for i in moves:
            v,co=comps[i]; co=[(r+direction,c) for r,c in co]; comps[i]=(v,co)
            for r,c in co:g[r][c]=v
    return g

